import { bootstrapApplication } from '@angular/platform-browser';
import { provideZonelessChangeDetection } from '@angular/core';
import { App } from './app/app';

bootstrapApplication(App, {
  providers: [
    provideZonelessChangeDetection(),
  ],
});

@Component({
  selector: 'app-topic-card',
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { '[class.is-active]': 'active()' },
  template: `
    <h3>{{ title() }}</h3>
    <button type="button" (click)="selected.emit(id())">Open</button>
  `,
})
export class TopicCard {
  readonly id = input.required<string>();
  readonly title = input.required<string>();
  readonly active = input(false);
  readonly selected = output<string>();
}

@if (modules().length > 0) {
  @for (mod of modules(); track mod.id) {
    <article>{{ mod.title }}</article>
  } @empty {
    <p>No matching modules.</p>
  }
} @else {
  <p>Loading curriculum...</p>
}

@Directive({
  selector: 'button[appCopyTrigger]',
  host: {
    '(click)': 'copyText()',
    '[attr.data-copied]': 'copied()',
  },
})
export class CopyTrigger {
  readonly text = input.required<string>({ alias: 'appCopyTrigger' });
  readonly copied = signal(false);

  async copyText() {
    await navigator.clipboard.writeText(this.text());
    this.copied.set(true);
    setTimeout(() => this.copied.set(false), 1500);
  }
}

export interface ApiConfig {
  baseUrl: string;
  timeoutMs: number;
}

export const API_CONFIG = new InjectionToken<ApiConfig>('API_CONFIG', {
  providedIn: 'root',
  factory: () => ({ baseUrl: '/api', timeoutMs: 8000 }),
});

@Injectable({ providedIn: 'root' })
export class CatalogClient {
  private readonly config = inject(API_CONFIG);
  private readonly http = inject(HttpClient);
}

export const routes: Routes = [
  {
    path: 'topics/:topicId',
    canActivate: [() => inject(SessionGuard).isReady()],
    loadComponent: () =>
      import('./topics/topic-detail').then((m) => m.TopicDetail),
  },
];

readonly noteForm = new FormGroup({
  title: new FormControl('', {
    nonNullable: true,
    validators: [Validators.required, Validators.minLength(4)],
  }),
  email: new FormControl('', {
    nonNullable: true,
    validators: [Validators.required, Validators.email],
  }),
});

export const authInterceptor: HttpInterceptorFn = (req, next) => {
  const token = inject(AuthStore).token();
  if (!token) return next(req);

  const authorizedReq = req.clone({
    setHeaders: { Authorization: `Bearer ${token}` },
  });
  return next(authorizedReq);
};

readonly count = signal(2);
readonly multiplier = signal(3);
readonly product = computed(() => this.count() * this.multiplier());
readonly isEven = computed(() => this.product() % 2 === 0);

increment() {
  this.count.update((n) => n + 1);
}

private readonly searchService = inject(SearchService);
readonly queryControl = new FormControl('', { nonNullable: true });

readonly results = toSignal(
  this.queryControl.valueChanges.pipe(
    debounceTime(200),
    distinctUntilChanged(),
    switchMap((q) => this.searchService.find(q)),
  ),
  { initialValue: [] },
);

@Injectable({ providedIn: 'root' })
export class BookmarksStore {
  private readonly _ids = signal<string[]>([]);
  readonly ids = this._ids.asReadonly();
  readonly count = computed(() => this._ids().length);

  toggle(id: string) {
    this._ids.update((list) =>
      list.includes(id) ? list.filter((x) => x !== id) : [...list, id],
    );
  }
}

